from collections import Counter
def transform(grid):
    H,W=len(grid),len(grid[0])
    flat=Counter(x for r in grid for x in r)
    bg=flat.most_common(1)[0][0]
    base={0,bg}
    pat=[r for r in range(H) if any(x not in base for x in grid[r])]
    if len(pat)<2: return [r[:] for r in grid]
    S={r:set(c for c,x in enumerate(grid[r]) if x not in base) for r in pat}
    best=(-1,1)
    for d in range(1,H):
        idn=pre=0
        for r in pat:
            r2=r+d
            if r2 in S:
                if grid[r]==grid[r2]: idn+=1
                elif S[r]<S[r2] or S[r2]<S[r]: pre+=1
        sc=3*idn+pre
        if sc>best[0]: best=(sc,d)
    d=best[1]
    out=[r[:] for r in grid]
    for r in pat:
        for r2 in (r-d,r+d):
            if 0<=r2<H:
                for c in range(W):
                    if out[r][c] in base and grid[r2][c] not in base:
                        out[r][c]=1
    return out

